// ── Validate incoming demo request ─────────────────────────────────────────
const body = $input.first().json?.body ?? $input.first().json ?? {};

const VALID_JOBS = ['debt-reminder', 'weekly-report', 'reminder-creation', 'cleanup'];

const jobType = body.job_type ?? body.jobType ?? null;
const userId  = body.user_id  ?? body.userId  ?? null;

if (!jobType) {
  throw new Error('Missing field: job_type. Valid values: ' + VALID_JOBS.join(', '));
}
if (!VALID_JOBS.includes(jobType)) {
  throw new Error(`Unknown job_type "${jobType}". Valid: ${VALID_JOBS.join(', ')}`);
}

console.log(`[Wariskan DEMO] ▶ Running job: ${jobType}${userId ? ` for user: ${userId}` : ' (all users)'}`);
console.log(`[Wariskan DEMO] Started at: ${new Date().toISOString()}`);

return [{ json: { jobType, userId, startedAt: new Date().toISOString() } }];

// ── Format demo output for the judge's screen ──────────────────────────────
const schedulerRes = $input.first().json;
const jobMeta      = $('Validate & Log Request').first().json;

const body = schedulerRes.body ?? schedulerRes;

// Visible in n8n execution log — this is the 'see, the agent is doing it' moment
console.log('═'.repeat(50));
console.log('🤖 WARISKAN DEMO — JOB RESULT');
console.log('═'.repeat(50));
console.log(`Job      : ${jobMeta.jobType}`);
console.log(`User     : ${jobMeta.userId ?? '(all users)'}`);
console.log(`Success  : ${body.success}`);
console.log(`Processed: ${body.processedCount ?? 'N/A'}`);
console.log(`Skipped  : ${body.skippedCount  ?? 'N/A'}`);
console.log(`Duration : ${body.durationMs    ?? 'N/A'} ms`);
if (body.errors?.length) {
  console.log(`Errors   : ${body.errors.length}`);
  body.errors.forEach((e, i) => console.log(`  [${i+1}] ${e}`));
}
console.log('═'.repeat(50));

// Structured output for respond node
const output = {
  job:          jobMeta.jobType,
  user:         jobMeta.userId ?? 'all',
  success:      body.success ?? false,
  processed:    body.processedCount ?? 0,
  skipped:      body.skippedCount  ?? 0,
  durationMs:   body.durationMs    ?? null,
  errors:       body.errors        ?? [],
  startedAt:    jobMeta.startedAt,
  finishedAt:   new Date().toISOString(),
};

return [{ json: output }];
